  document.addEventListener('click',async event=>{
    const el=event.target.closest('[data-action]');if(!el||!el.closest('#bee-immersive-suite'))return;const action=el.dataset.action;if(!action.startsWith('ps102-'))return;event.preventDefault();event.stopImmediatePropagation();const t=ps102Text;
    if(action.startsWith('ps102-link:')){window.open(ps102Links[action.split(':')[1]],'_blank','noopener');return;}
    if(action==='ps102-story'){rOpenModal('ps102-story');return;}
    if(action==='ps102-update'){state.ps102Downloading=false;rOpenModal('ps102-update');return;}
    if(action==='ps102-mirrors'){rOpenModal('ps102-mirrors');return;}
    if(action==='ps102-back-update'){rOpenModal('ps102-update');return;}
    if(action.startsWith('ps102-mirror:')){state.ps102Mirror=Number(action.split(':')[1]);rOpenModal('ps102-update');return;}
    if(action.startsWith('ps102-shot:')){state.ps102Shot=Number(action.split(':')[1]);rOpenModal('ps102-shot');return;}
    if(action==='ps102-back-product'){rOpenModal('ps102-product-assets');return;}
    if(action==='ps102-copy-email'){try{await navigator.clipboard.writeText('sunxiaoyes@outlook.com');notice(t.productPromoCopiedToast);}catch(_){sheet(t.productPromoEmailLabel,'<textarea readonly>sunxiaoyes@outlook.com</textarea>');}return;}
    if(action==='ps102-download'){state.ps102Downloading=true;rOpenModal('ps102-update');return;}
    if(action==='ps102-update-cancel'||action==='ps102-close'){state.ps102Downloading=false;rDismiss();return;}
    if(action.startsWith('ps102-product:')){rOpenModal('ps102-product-'+action.split(':')[1]);return;}
    if(action==='ps102-doc-retry'){state.ps102DocRetry=true;render();return;}
    if(action.startsWith('ps102-doc:')){state.ps102DocRetry=false;navigate('flow-support-'+(action.endsWith('privacy')?'privacy':'changelog'));return;}
    if(action==='ps102-open-shortcuts'){window.location.href='shortcuts://';return;}
    if(action.startsWith('ps102-copy:')){const text=ps102Shortcuts[Number(action.split(':')[1])][2];try{await navigator.clipboard.writeText(text);notice(t.shortcutUrlCopied);}catch(_){sheet(t.shortcutUrlCopied,`<textarea readonly>${esc(text)}</textarea>`);}return;}
    if(action.startsWith('ps102-donation:')){sheet(t.donationTitle,`<div class="ps102-modal"><p>QA · ${esc(t.donationNoFeatures)}</p>${btn('close',esc(t.commonCancel),t.commonCancel,'bc-secondary')}</div>`);return;}
    if(action==='ps102-gallery')notice('V4 组件验收 · 局部设计示例');
  },true);
